import{_ as e,o as t,c as s,ai as n}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"CRM 客户关系管理系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/business/crm.md","filePath":"instances/business/crm.md"}'),r={name:"instances/business/crm.md"};function i(d,a,l,o,p,c){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="crm-客户关系管理系统" tabindex="-1">CRM 客户关系管理系统 <a class="header-anchor" href="#crm-客户关系管理系统" aria-label="Permalink to “CRM 客户关系管理系统”">​</a></h1><blockquote><p>✅ 已验证（OpenBiz 第 4 个独立消费者） · 所属模块：<a href="/my-vitepress-site/instances/business/">03 企业业务应用</a> · 模块优先级：第 2 位 · 工程 <code>openbiz-crm-app</code></p></blockquote><h2 id="📌-项目简介" tabindex="-1">📌 项目简介 <a class="header-anchor" href="#📌-项目简介" aria-label="Permalink to “📌 项目简介”">​</a></h2><p>CRM 管理「<strong>客户 → 商机 → 成交</strong>」的销售全链路。它把客户档案与销售过程沉淀为可流转、可统计的结构化数据，是销售团队跟进客户、销售主管看漏斗的统一入口。</p><ul><li><strong>面向用户</strong>：销售（建客户 / 推商机）、销售主管（看漏斗与阶段转化）</li><li><strong>核心价值</strong>：客户与商机不再散落在 Excel / 微信里，而是有状态机约束、可统计的资产</li></ul><h2 id="🗺️-功能规划" tabindex="-1">🗺️ 功能规划 <a class="header-anchor" href="#🗺️-功能规划" aria-label="Permalink to “🗺️ 功能规划”">​</a></h2><h3 id="✅-已实现-e2e-已验证" tabindex="-1">✅ 已实现（E2E 已验证） <a class="header-anchor" href="#✅-已实现-e2e-已验证" aria-label="Permalink to “✅ 已实现（E2E 已验证）”">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>能做什么</th><th>证据</th></tr></thead><tbody><tr><td>客户档案</td><td><code>NEW → ACTIVE → CHURNED</code>，活动态可转 <code>INVALID</code>（逻辑删除）</td><td>客户状态机 E2E</td></tr><tr><td>商机管理</td><td><code>DRAFT → NEGOTIATING → WON / LOST</code>；<code>DRAFT/NEGOTIATING → CANCELLED</code>；WON/LOST/CANCELLED 为终态</td><td>商机状态机 E2E</td></tr><tr><td>销售漏斗统计</td><td><code>GET /api/crm/opportunities/stats</code> 按阶段聚合商机数与金额</td><td>统计断言通过</td></tr><tr><td>非法流转拦截</td><td>WON 再谈判、NEW 直接流失均被拒 <code>ILLEGAL_TRANSITION</code></td><td>E2E</td></tr><tr><td>多租户</td><td>复用 <code>openbiz-saas-core</code> + RuoYi 登录外壳</td><td>独立库 <code>openbiz_crm</code></td></tr></tbody></table><h3 id="📋-待做-规划" tabindex="-1">📋 待做 / 规划 <a class="header-anchor" href="#📋-待做-规划" aria-label="Permalink to “📋 待做 / 规划”">​</a></h3><ul><li>[ ] <strong>销售线索层</strong>：线索录入 / 来源追踪 / 分配回收——当前客户直接跳商机，漏斗上游是断的</li><li>[ ] <strong>客户跟进</strong>：跟进记录、下次联系提醒、沟通时间线</li><li>[ ] <strong>客户主数据增强</strong>：联系人、标签分类、查重合并</li><li>[ ] <strong>行级数据权限</strong>：销售团队 / 角色的数据隔离（当前只到登录级）</li><li>[ ] <strong>时间维度统计</strong>：赢单率趋势、阶段停留时长</li></ul><h2 id="🏗️-技术架构" tabindex="-1">🏗️ 技术架构 <a class="header-anchor" href="#🏗️-技术架构" aria-label="Permalink to “🏗️ 技术架构”">​</a></h2><h3 id="平台-垂直定位" tabindex="-1">平台 + 垂直定位 <a class="header-anchor" href="#平台-垂直定位" aria-label="Permalink to “平台 + 垂直定位”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌ 垂直应用层（薄：领域模型 + 表单/流程配置）</span></span>
<span class="line"><span>│   CRM · ERP · PMS · OA · BPM · Form        ◀ 本页：CRM</span></span>
<span class="line"><span>├ 平台内核 · OpenBiz（一次建深，覆盖通用能力约 80%）</span></span>
<span class="line"><span>│   多租户/数据隔离 · RBAC/行级权限 · 工作流引擎 · 动态表单引擎</span></span>
<span class="line"><span>│   审计日志 · 消息通知中心 · 导入导出/报表 · 开放 API/SSO</span></span>
<span class="line"><span>└ 数据层 · MySQL 8 · Redis · 对象存储 · 消息队列</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>CRM 是<strong>薄垂直层</strong>：只实现客户 / 商机状态机与漏斗统计，多租户、登录、权限、消息全部复用平台内核。</p><h3 id="本模块内部结构" tabindex="-1">本模块内部结构 <a class="header-anchor" href="#本模块内部结构" aria-label="Permalink to “本模块内部结构”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vue3 前端（客户 / 商机 / 漏斗）</span></span>
<span class="line"><span>   │ REST</span></span>
<span class="line"><span>Controller → Service（状态机校验）→ Mapper</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>MySQL \`openbiz_crm\`（customer / opportunity）</span></span>
<span class="line"><span>   ▲ 复用 openbiz-saas-core（TenantContext 多租户）+ RuoYi 登录外壳</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="🧰-技术栈-开发语言" tabindex="-1">🧰 技术栈 / 开发语言 <a class="header-anchor" href="#🧰-技术栈-开发语言" aria-label="Permalink to “🧰 技术栈 / 开发语言”">​</a></h2><table tabindex="0"><thead><tr><th>分层</th><th>技术</th></tr></thead><tbody><tr><td>后端</td><td>Java 21 + Spring Boot 3 + MyBatis</td></tr><tr><td>前端</td><td>Vue 3 + TypeScript</td></tr><tr><td>数据库</td><td>MySQL 8（独立库 <code>openbiz_crm</code>）</td></tr><tr><td>底座</td><td>OpenBiz <code>openbiz-saas-core</code> + RuoYi 登录外壳</td></tr><tr><td>部署</td><td>独立端口 18084 + 独立库</td></tr></tbody></table><h2 id="✅-支持什么-能力边界" tabindex="-1">✅ 支持什么（能力边界） <a class="header-anchor" href="#✅-支持什么-能力边界" aria-label="Permalink to “✅ 支持什么（能力边界）”">​</a></h2><ul><li><strong>支持</strong>：单租户内客户生命周期管理、商机阶段流转、按阶段漏斗统计、非法流转拦截</li><li><strong>暂不支持</strong>：线索管理、跟进提醒、行级数据权限、跨时间趋势分析</li></ul><h2 id="🚀-开发路线" tabindex="-1">🚀 开发路线 <a class="header-anchor" href="#🚀-开发路线" aria-label="Permalink to “🚀 开发路线”">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td>M1</td><td>客户 + 商机最小闭环（状态机 + 漏斗）</td><td>✅ 完成</td></tr><tr><td>M2</td><td>销售线索层（录入 / 来源 / 分配）</td><td>📋 规划</td></tr><tr><td>M3</td><td>客户跟进与提醒</td><td>📋 规划</td></tr><tr><td>M4</td><td>行级数据权限 + 趋势统计</td><td>📋 规划</td></tr></tbody></table><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to “🔗 相关资源”">​</a></h2><ul><li>平台内核：<a href="/my-vitepress-site/instances/platform.html">平台内核 · OpenBiz</a></li><li>实证记录：<a href="/my-vitepress-site/apps/openbiz/crm/">OpenBiz 实战 › CRM</a></li><li>工程位置：<code>E:/8.cangku/for-job/openbiz-crm-app</code>（端口 18084，含 README 与 E2E 脚本）</li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/business/">03 企业业务应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>`,26)])])}const m=e(r,[["render",i]]);export{b as __pageData,m as default};
